46	void
47	xlockmore_setup (struct xscreensaver_function_table *xsft, void *arg)
48	{
49	  struct xlockmore_function_table *xlmft = 
50	    (struct xlockmore_function_table *) arg;
51	  int i, j;
52	  char *s;
53	  XrmOptionDescRec *new_options;
54	  char **new_defaults;
55	  const char *xlockmore_defaults;
56	  ModeSpecOpt *xlockmore_opts = xlmft->opts;
57	
58	# undef ya_rand_init
59	  ya_rand_init (0);
60	
61	  xsft->init_cb    = (void *(*) (Display *, Window)) xlockmore_init;
62	  xsft->draw_cb    = xlockmore_draw;
63	  xsft->reshape_cb = xlockmore_reshape;
64	  xsft->event_cb   = xlockmore_event;
65	  xsft->free_cb    = xlockmore_free;
66	
67	  progclass = xlmft->progclass;
68	  xlockmore_defaults = xlmft->defaults;
69	
70	  /* Translate the xlockmore `opts[]' argument to a form that
71	     screenhack.c expects.
72	
73	     Some of the strings in here are leaked at exit, but since this code
74	     only runs on X11, that doesn't matter.
75	   */
76	  new_options = (XrmOptionDescRec *) 
77	    calloc (xlockmore_opts->numopts*3 + 100, sizeof (*new_options));
78	
79	  for (i = 0; i < xlockmore_opts->numopts; i++)
80	    {
81	      XrmOptionDescRec *old = &xlockmore_opts->opts[i];
82	      XrmOptionDescRec *new = &new_options[i];
83	
84	      if (old->option[0] == '-')
85		new->option = old->option;
86	      else
87		{
88		  /* Convert "+foo" to "-no-foo". */
89		  new->option = (char *) malloc (strlen(old->option) + 5);
90		  strcpy (new->option, "-no-");
91		  strcat (new->option, old->option + 1);
92		}
93	
94	      new->specifier = strrchr (old->specifier, '.');
95	      if (!new->specifier) abort();
96	
97	      new->argKind = old->argKind;
98	      new->value = old->value;
99	    }
100	
101	  /* Add extra args, if they're mentioned in the defaults... */
102	  {
103	    char *args[] = { "-count", "-cycles", "-delay", "-ncolors",
104			     "-size", "-font", "-wireframe", "-use3d", "-useSHM" };
105	    for (j = 0; j < countof(args); j++)
106	      if (strstr(xlockmore_defaults, args[j]+1))
107		{
108		  XrmOptionDescRec *new = &new_options[i++];
109		  new->option = args[j];
110		  new->specifier = strdup(args[j]);
111		  new->specifier[0] = '.';
112		  if (!strcmp(new->option, "-wireframe"))
113		    {
114		      new->argKind = XrmoptionNoArg;
115		      new->value = "True";
116		      new = &new_options[i++];
117		      new->option = "-no-wireframe";
118		      new->specifier = new_options[i-2].specifier;
119		      new->argKind = XrmoptionNoArg;
120		      new->value = "False";
121		    }
122		  else if (!strcmp(new->option, "-use3d"))
123		    {
124		      new->option = "-3d";
125		      new->argKind = XrmoptionNoArg;
126		      new->value = "True";
127		      new = &new_options[i++];
128		      new->option = "-no-3d";
129		      new->specifier = new_options[i-2].specifier;
130		      new->argKind = XrmoptionNoArg;
131		      new->value = "False";
132		    }
133		  else if (!strcmp(new->option, "-useSHM"))
134		    {
135		      new->option = "-shm";
136		      new->argKind = XrmoptionNoArg;
137		      new->value = "True";
138		      new = &new_options[i++];
139		      new->option = "-no-shm";
140		      new->specifier = new_options[i-2].specifier;
141		      new->argKind = XrmoptionNoArg;
142		      new->value = "False";
143		    }
144		  else
145		    {
146		      new->argKind = XrmoptionSepArg;
147		      new->value = 0;
148		    }
149		}
150	  }
151	
152	
153	
154	  /* Construct the kind of `defaults' that screenhack.c expects from
155	     the xlockmore `vars[]' argument.
156	   */
157	  i = 0;
158	
159	  new_defaults = (char **) calloc (1, xlockmore_opts->numvarsdesc * 10 + 1000);
160	
161	  /* Put on the PROGCLASS.background/foreground resources. */
162	  s = (char *) malloc(50);
163	  *s = 0;
164	# ifndef HAVE_JWXYZ
165	  strcpy (s, progclass);
166	# endif
167	  strcat (s, ".background: black");
168	  new_defaults [i++] = s;
169	
170	  s = (char *) malloc(50);
171	  *s = 0;
172	# ifndef HAVE_JWXYZ
173	  strcpy (s, progclass);
174	# endif
175	  strcat (s, ".foreground: white");
176	  new_defaults [i++] = s;
177	
178	  /* Copy the lines out of the `xlockmore_defaults' var and into this array. */
179	  s = strdup (xlockmore_defaults);
180	  while (s && *s)
181	    {
182	      new_defaults [i++] = s;
183	      s = strchr(s, '\n');
184	      if (s)
185		*s++ = 0;
186	    }
187	
188	  /* Copy the defaults out of the `xlockmore_opts->' variable. */
189	  for (j = 0; j < xlockmore_opts->numvarsdesc; j++)
190	    {
191	      const char *def = xlockmore_opts->vars[j].def;
192	
193	      if (!def) abort();
194	      if (!*def) abort();
195	      if (strlen(def) > 1000) abort();
196	
197	      s = (char *) malloc (strlen (xlockmore_opts->vars[j].name) +
198				   strlen (def) + 10);
199	      strcpy (s, "*");
200	      strcat (s, xlockmore_opts->vars[j].name);
201	      strcat (s, ": ");
202	      strcat (s, def);
203	      new_defaults [i++] = s;
204	
205	      /* Go through the list of resources and print a warning if there
206	         are any duplicates.
207	       */
208	      {
209	        char *onew = strdup (xlockmore_opts->vars[j].name);
210	        const char *new = onew;
211	        int k;
212	        if ((s = strrchr (new, '.'))) new = s+1;
213	        if ((s = strrchr (new, '*'))) new = s+1;
214	        for (k = 0; k < i-1; k++)
215	          {
216	            char *oold = strdup (new_defaults[k]);
217	            const char *old = oold;
218	            if ((s = strchr (oold, ':'))) *s = 0;
219	            if ((s = strrchr (old, '.'))) old = s+1;
220	            if ((s = strrchr (old, '*'))) old = s+1;
221	            if (!strcasecmp (old, new))
222	              {
223	                fprintf (stderr,
224	                         "%s: duplicate resource \"%s\": "
225	                         "set in both DEFAULTS and vars[]\n",
226	                         progname, old);
227	              }
228	            free (oold);
229	          }
230	        free (onew);
231	      }
232	    }
233	
234	  new_defaults [i] = 0;
235	
236	  xsft->progclass = progclass;
237	  xsft->options   = new_options;
238	  xsft->defaults  = (const char * const *) new_defaults;
239	}
