242	static void
243	xlockmore_release_screens (ModeInfo *mi)
244	{
245	  struct xlockmore_function_table *xlmft = mi->xlmft;
246	
247	  /* 2. Call release_##, if it exists. */
248	  if (xlmft->hack_release)
249	    xlmft->hack_release (mi);
250	
251	  /* 3. Free the state array. */
252	  if (xlmft->state_array) {
253	    free(*xlmft->state_array);
254	    *xlmft->state_array = NULL;
255	    xlmft->state_array = NULL;
256	  }
257	
258	  /* 4. Pretend FreeAllGL(mi) gets called here. */
259	
260	  mi->xlmft->got_init = 0;
261	}
