271	static void
272	xlockmore_free_screens (ModeInfo *mi)
273	{
274	  struct xlockmore_function_table *xlmft = mi->xlmft;
275	
276	  /* Optimization: xlockmore_read_resources calls this lots on first start. */
277	  if (!xlmft->got_init)
278	    return;
279	
280	  /* Order is important here: */
281	
282	  /* 1. Call free_## for all screens. */
283	  if (xlmft->hack_free) {
284	    int old_screen = mi->screen_number;
285	    for (mi->screen_number = 0; mi->screen_number < XLOCKMORE_NUM_SCREENS;
286	         ++mi->screen_number) {
287	      if (xlockmore_got_init(mi))
288	        xlmft->hack_free (mi); /* got_init is reset in xlockmore_release_screens. */
289	    }
290	    mi->screen_number = old_screen;
291	  }
292	
293	  xlockmore_release_screens (mi);
294	}
