297	static void
298	xlockmore_read_resources (ModeInfo *mi)
299	{
300	  Display *dpy = mi->dpy;
301	  ModeSpecOpt *xlockmore_opts = mi->xlmft->opts;
302	  int i;
303	  for (i = 0; i < xlockmore_opts->numvarsdesc; i++)
304	    {
305	      void  *var   = xlockmore_opts->vars[i].var;
306	      Bool  *var_b = (Bool *)  var;
307	      char **var_c = (char **) var;
308	      int   *var_i = (int *) var;
309	      float *var_f = (float *) var;
310	
311	      /* If any of the options changed, stop this hack's other instances. */
312	      switch (xlockmore_opts->vars[i].type)
313	        {
314	        case t_String:
315	          {
316	            char *c = get_string_resource (dpy, xlockmore_opts->vars[i].name,
317	                                           xlockmore_opts->vars[i].classname);
318	            if ((!c && !*var_c) || (c && *var_c && !strcmp(c, *var_c))) {
319	              free (c);
320	            } else {
321	              xlockmore_free_screens (mi);
322	              if (*var_c) free (*var_c);
323	              *var_c = c;
324	            }
325	          }
326	          break;
327	        case t_Float:
328	          {
329	            float f = get_float_resource (dpy, xlockmore_opts->vars[i].name,
330	                                          xlockmore_opts->vars[i].classname);
331	            float frac = fabsf(*var_f) * (1.0f / (1l << (FLT_MANT_DIG - 4)));
332	            if (f < *var_f - frac || f > *var_f + frac) {
333	              xlockmore_free_screens (mi);
334	              *var_f = f;
335	            }
336	          }
337	          break;
338	        case t_Int:
339	          {
340	            int ii = get_integer_resource (dpy, xlockmore_opts->vars[i].name,
341	                                          xlockmore_opts->vars[i].classname);
342	            if (ii != *var_i) {
343	              xlockmore_free_screens (mi);
344	              *var_i = ii;
345	            }
346	          }
347	          break;
348	        case t_Bool:
349	          {
350	            Bool b = get_boolean_resource (dpy, xlockmore_opts->vars[i].name,
351	                                           xlockmore_opts->vars[i].classname);
352	            if (b != *var_b) {
353	              xlockmore_free_screens (mi);
354	              *var_b = b;
355	            }
356	          }
357	          break;
358	        default:
359	          abort ();
360	        }
361	    }
362	}
