365	/* We keep a list of all of the screen numbers that are in use and not
366	   yet freed so that they can have sensible screen numbers.  If three
367	   displays are created (0, 1, 2) and then #1 is closed, then the fourth
368	   display will be given the now-unused display number 1. (Everything in
369	   here assumes a 1:1 Display/Screen mapping.)
370	
371	   XLOCKMORE_NUM_SCREENS is the most number of live displays at one time. So
372	   if it's 64, then we'll blow up if the system has 64 monitors and also has
373	   System Preferences open (the small preview window).
374	
375	   Note that xlockmore-style savers tend to allocate big structures, so
376	   setting XLOCKMORE_NUM_SCREENS to 1000 will waste a few megabytes.  Also
377	   most (all?) of them assume that the number of screens never changes, so
378	   dynamically expanding this array won't work.
379	 */
380	
381	
382	static void *
383	xlockmore_init (Display *dpy, Window window, 
384	                struct xlockmore_function_table *xlmft)
385	{
386	  ModeInfo *mi = (ModeInfo *) calloc (1, sizeof(*mi));
387	  XGCValues gcv;
388	  XColor color;
389	  int i;
390	  Bool root_p;
391	
392	  if (! xlmft)
393	    abort();
394	  mi->xlmft = xlmft;
395	
396	  mi->dpy = dpy;
397	  mi->window = window;
398	  XGetWindowAttributes (dpy, window, &mi->xgwa);
399	  
400	  /* In Cocoa and Android-based xscreensaver, as well as with DEBUG_PAIR,
401	     hacks run in the same address space, so each one needs to get its own
402	     screen number.
403	
404	     Find the first empty slot in live_displays and plug us in.
405	   */
406	  {
407	    const int size = XLOCKMORE_NUM_SCREENS;
408	    int i;
409	    for (i = 0; i < size; i++) {
410	      if (! (xlmft->live_displays & (1ul << i)))
411	        break;
412	    }
413	    if (i >= size) abort();
414	    xlmft->live_displays |= 1ul << i;
415	    xlmft->got_init &= ~(1ul << i);
416	    mi->screen_number = i;
417	  }
418	
419	  root_p = (window == RootWindowOfScreen (mi->xgwa.screen));
420	
421	#ifndef HAVE_JWXYZ
422	
423	  /* Everybody gets motion events, just in case. */
424	  XSelectInput (dpy, window, (mi->xgwa.your_event_mask | PointerMotionMask));
425	
426	#endif /* !HAVE_JWXYZ */
427	
428	  if (mi->xlmft->hack_release) {
429	/*
430	    fprintf (
431	      stderr,
432	      "%s: WARNING: hack_release is not usually recommended; see MI_INIT.\n",
433	      progname);
434	*/
435	  }
436	
437	  color.flags = DoRed|DoGreen|DoBlue;
438	  color.red = color.green = color.blue = 0;
439	  if (!XAllocColor(dpy, mi->xgwa.colormap, &color))
440	    abort();
441	  mi->black = color.pixel;
442	  color.red = color.green = color.blue = 0xFFFF;
443	  if (!XAllocColor(dpy, mi->xgwa.colormap, &color))
444	    abort();
445	  mi->white = color.pixel;
446	
447	  if (mono_p)
448	    {
449	      static XColor colors[2];
450	    MONO:
451	      mi->npixels = 2;
452	      if (! mi->pixels)
453	        mi->pixels = (unsigned long *) 
454	          calloc (mi->npixels, sizeof (*mi->pixels));
455	      if (!mi->colors)
456	        mi->colors = (XColor *) 
457	          calloc (mi->npixels, sizeof (*mi->colors));
458	      colors[0].flags = DoRed|DoGreen|DoBlue;
459	      colors[1].flags = DoRed|DoGreen|DoBlue;
460	      colors[0].red = colors[0].green = colors[0].blue = 0;
461	      colors[1].red = colors[1].green = colors[1].blue = 0xFFFF;
462	      mi->writable_p = False;
463	    }
464	  else
465	    {
466	      mi->npixels = get_integer_resource (dpy, "ncolors", "Integer");
467	      if (mi->npixels <= 0)
468		mi->npixels = 64;
469	      else if (mi->npixels > MAX_COLORS)
470		mi->npixels = MAX_COLORS;
471	
472	      mi->colors = (XColor *) calloc (mi->npixels, sizeof (*mi->colors));
473	
474	      mi->writable_p = mi->xlmft->want_writable_colors;
475	
476	      switch (mi->xlmft->desired_color_scheme)
477	        {
478	        case color_scheme_uniform:
479	          make_uniform_colormap (mi->xgwa.screen, mi->xgwa.visual,
480	                                 mi->xgwa.colormap,
481	                                 mi->colors, &mi->npixels,
482	                                 True, &mi->writable_p, True);
483	          break;
484	        case color_scheme_smooth:
485	          make_smooth_colormap (mi->xgwa.screen, mi->xgwa.visual,
486	                                mi->xgwa.colormap,
487	                                mi->colors, &mi->npixels,
488	                                True, &mi->writable_p, True);
489	          break;
490	        case color_scheme_bright:
491	        case color_scheme_default:
492	          make_random_colormap (mi->xgwa.screen, mi->xgwa.visual,
493	                                mi->xgwa.colormap,
494	                                mi->colors, &mi->npixels,
495	                                (mi->xlmft->desired_color_scheme ==
496	                                 color_scheme_bright),
497	                                True, &mi->writable_p, True);
498	          break;
499	        default:
500	          abort();
501	        }
502	
503	      if (mi->npixels <= 2)
504		goto MONO;
505	      else
506		{
507		  mi->pixels = (unsigned long *)
508		    calloc (mi->npixels, sizeof (*mi->pixels));
509		  for (i = 0; i < mi->npixels; i++)
510		    mi->pixels[i] = mi->colors[i].pixel;
511		}
512	    }
513	
514	  gcv.foreground = mi->white;
515	  gcv.background = mi->black;
516	  mi->gc = XCreateGC (dpy, window, GCForeground|GCBackground, &gcv);
517	
518	  mi->fullrandom = True;
519	
520	  mi->pause      = get_integer_resource (dpy, "delay", "Usecs");
521	
522	  mi->cycles     = get_integer_resource (dpy, "cycles", "Int");
523	  mi->batchcount = get_integer_resource (dpy, "count", "Int");
524	  mi->size	 = get_integer_resource (dpy, "size", "Int");
525	
526	  mi->threed = get_boolean_resource (dpy, "use3d", "Boolean");
527	  mi->threed_delta = get_float_resource (dpy, "delta3d", "Float");
528	  mi->threed_right_color = get_pixel_resource (dpy,
529						       mi->xgwa.colormap, "right3d", "Color");
530	  mi->threed_left_color = get_pixel_resource (dpy,
531					 	      mi->xgwa.colormap, "left3d", "Color");
532	  mi->threed_both_color = get_pixel_resource (dpy,
533						      mi->xgwa.colormap, "both3d", "Color");
534	  mi->threed_none_color = get_pixel_resource (dpy,
535						      mi->xgwa.colormap, "none3d", "Color");
536	
537	  mi->wireframe_p = get_boolean_resource (dpy, "wireframe", "Boolean");
538	  mi->root_p = root_p;
539	  mi->fps_p = get_boolean_resource (dpy, "doFPS", "DoFPS");
540	  mi->recursion_depth = -1;  /* see fps.c */
541	
542	  if (mi->pause < 0)
543	    mi->pause = 0;
544	  else if (mi->pause > 100000000)
545	    mi->pause = 100000000;
546	  
547	  xlockmore_read_resources (mi);
548	
549	  return mi;
550	}
