563	static void
564	xlockmore_do_init (ModeInfo *mi)
565	{
566	# ifdef HAVE_JWZGLES
567	  if (mi->xlmft->jwzgles_make_current && mi->jwzgles_state)
568	    mi->xlmft->jwzgles_make_current (mi->jwzgles_state);
