600	static unsigned long
601	xlockmore_draw (Display *dpy, Window window, void *closure)
602	{
603	  ModeInfo *mi = (ModeInfo *) closure;
604	  unsigned long orig_pause = mi->pause;
605	  unsigned long this_pause;
606	
607	# ifdef HAVE_JWZGLES
608	  if (mi->xlmft->jwzgles_make_current && mi->jwzgles_state)
609	    mi->xlmft->jwzgles_make_current (mi->jwzgles_state);
610	# endif
611	
612	  if (mi->needs_clear) {
613	    /* OpenGL hacks never get here. */
614	    if (!mi->is_drawn) {
615	      xlockmore_clear (mi);
616	    } else {
617	      mi->eraser = erase_window (dpy, window, mi->eraser);
618	      /* Delay calls to xlockmore hooks while the erase animation is running. */
