671	xlockmore_event (Display *dpy, Window window, void *closure, XEvent *event)
672	{
673	  ModeInfo *mi = (ModeInfo *) closure;
674	
675	# ifdef HAVE_JWZGLES
676	  if (mi->xlmft->jwzgles_make_current && mi->jwzgles_state)
677	    mi->xlmft->jwzgles_make_current (mi->jwzgles_state);
678	# endif
679	
680	  if (mi) {
681	    if (mi->xlmft->hack_handle_events) {
682	      xlockmore_check_init (mi);
683	      return mi->xlmft->hack_handle_events (mi, event);
684	    }
685	
686	    if (screenhack_event_helper (mi->dpy, mi->window, event)) {
687	      /* If a clear is in progress, don't interrupt or restart it. */
688	      if (mi->needs_clear) {
689	        if (mi->xlmft->hack_free)
690	          mi->xlmft->hack_free (mi);
