710	static void
711	xlockmore_free (Display *dpy, Window window, void *closure)
712	{
713	  ModeInfo *mi = (ModeInfo *) closure;
714	
715	# ifdef HAVE_JWZGLES
716	  if (mi->xlmft->jwzgles_make_current && mi->jwzgles_state)
717	    mi->xlmft->jwzgles_make_current (mi->jwzgles_state);
718	# endif
719	
720	  if (mi->eraser)
721	    eraser_free (mi->eraser);
722	
723	  /* Some hacks may need to do things with their Display * on cleanup. And
724	     under JWXYZ, the Display * for this hack gets cleaned up right after
725	     xlockmore_free returns. Thus, hack_free has to happen now, rather than
726	     after the final screen has been released.
727	   */
728	  if (mi->xlmft->hack_free && xlockmore_got_init(mi)) {
729	    mi->xlmft->hack_free (mi);
730	    mi->xlmft->got_init &= ~(1ul << mi->screen_number);
731	  }
732	
733	  /* Find us in live_displays and clear that slot. */
734	  assert (mi->xlmft->live_displays & (1ul << mi->screen_number));
735	  mi->xlmft->live_displays &= ~(1ul << mi->screen_number);
736	  if (!mi->xlmft->live_displays)
737	    xlockmore_release_screens (mi);
738	
739	  XFreeGC (dpy, mi->gc);
740	  free_colors (mi->xgwa.screen, mi->xgwa.colormap, mi->colors, mi->npixels);
741	  free (mi->colors);
742	  free (mi->pixels);
743	
744	# ifdef HAVE_JWZGLES
745	  if (mi->xlmft->jwzgles_free)
746	    mi->xlmft->jwzgles_free();
747	# endif /* HAVE_JWZGLES */
748	
749	  free (mi);
750	}
