753	void
754	xlockmore_mi_init (ModeInfo *mi, size_t state_size, void **state_array)
755	{
756	  struct xlockmore_function_table *xlmft = mi->xlmft;
757	
758	  /* Steal the state_array for safe keeping.
759	     Only necessary when the screenhack isn't a once per process deal.
760	     (i.e. macOS, iOS, Android)
761	   */
762	  assert ((!xlmft->state_array && !*state_array) ||
763	          xlmft->state_array == state_array);
764	  xlmft->state_array = state_array;
765	
766	  if (!*xlmft->state_array) {
767	    *xlmft->state_array = calloc (XLOCKMORE_NUM_SCREENS, state_size);
768	
769	    if (!*xlmft->state_array) {
770	#ifdef HAVE_JWXYZ
771	      /* Throws an exception instead of exiting the process. */
772	      jwxyz_abort ("%s: out of memory", progname);
773	#else
774	      fprintf (stderr, "%s: out of memory\n", progname);
775	      exit (1);
776	#endif
777	    }
778	  }
779	
780	  /* Find the appropriate state object, clear it, and we're done. */
781	  {
782	    if (xlmft->hack_free && xlockmore_got_init(mi))
783	      xlmft->hack_free (mi); /* Don't reset the got_init bit from MI_INIT. */
784	    memset ((char *)(*xlmft->state_array) + mi->screen_number * state_size, 0,
785	            state_size);
786	  }
787	}
